-- Publicación atómica del grupo Helado casero de vainilla (7 idiomas) — 2026-10-06
-- Requisito previo: PR de Helado desplegado (imágenes /recetas/receta-helado-casero/* respondiendo 200).
do $pub$
declare
  g constant uuid := 'b7214663-c9ba-4062-b363-d651d2faec96';
  es_id constant uuid := '3e61f93e-b80b-45d2-8f52-d6af6c439784';
  j constant jsonb := $j$[
{"id":"3e61f93e-b80b-45d2-8f52-d6af6c439784","recipe_group_id":"b7214663-c9ba-4062-b363-d651d2faec96","language":"es","slug":"receta-helado-casero","public_path":"/receta-helado-casero","source_url":"https://manualdecocina.com/receta-helado-casero/","title":"Helado casero de vainilla","excerpt":"Helado de vainilla cremoso hecho con una base de crema, leche, yemas y azúcar, con o sin heladera. Rinde 6 raciones; necesita 4 horas de reposo en frío.","summary":"Este helado casero de vainilla parte de una crema inglesa: crema de leche y leche calientes con azúcar, templadas sobre yemas y cocinadas hasta que cubran el dorso de una cuchara. Después se enfría, se aromatiza con extracto de vainilla y se bate en heladera o se congela removiendo.\n\nEl resultado es un helado suave, con sabor limpio a vainilla y textura cremosa. Rinde 6 raciones y requiere unas 4 horas de refrigeración antes de congelar.","category":"Postres","difficulty":"Fácil","course":"Postre","cuisine":"Postres fríos","prep_time_minutes":25,"cook_time_minutes":15,"total_time_minutes":280,"servings":6,"keywords":["helado casero de vainilla","helado de vainilla","receta de helado casero","helado con yemas","helado sin heladera","postre frío"],"ingredients":[{"name":"crema de leche","amount":"200","unit":"ml","group":"Base de crema"},{"name":"leche entera","amount":"200","unit":"ml","group":"Base de crema"},{"name":"azúcar","amount":"150","unit":"g","group":"Base de crema"},{"name":"yemas de huevo","amount":"4","unit":"unidad","group":"Base de crema"},{"name":"extracto de vainilla","amount":"5","unit":"ml","group":"Para aromatizar"}],"steps":[{"title":"Calienta la crema y la leche","content":"En una olla, calienta a fuego medio 200 ml de crema de leche y 200 ml de leche sin dejar que hiervan. Añade 150 g de azúcar y remueve hasta que se disuelva.","image_url":"/recetas/receta-helado-casero/paso-01.webp","image_alt":"Helado casero de vainilla: Calienta la crema y la leche"},{"title":"Bate las yemas","content":"En un recipiente aparte, bate 4 yemas de huevo con unas varillas.","image_url":"/recetas/receta-helado-casero/paso-02.webp","image_alt":"Helado casero de vainilla: Bate las yemas"},{"title":"Tempera las yemas","content":"Vierte poco a poco parte de la mezcla caliente sobre las yemas, removiendo sin parar, para templarlas sin que se cuajen.","image_url":"/recetas/receta-helado-casero/paso-03.webp","image_alt":"Helado casero de vainilla: Tempera las yemas"},{"title":"Cocina la crema","content":"Devuelve todo a la olla y cocina a fuego medio-bajo, removiendo, hasta que la crema espese ligeramente y cubra el dorso de una cuchara.","image_url":"/recetas/receta-helado-casero/paso-04.webp","image_alt":"Helado casero de vainilla: Cocina la crema"},{"title":"Enfría la crema","content":"Retira del fuego, deja enfriar y refrigera al menos 4 horas, tapada con film en contacto con la superficie.","image_url":"/recetas/receta-helado-casero/paso-05.webp","image_alt":"Helado casero de vainilla: Enfría la crema"},{"title":"Bate o congela","content":"Añade 5 ml de extracto de vainilla y bate en una heladera siguiendo sus instrucciones. Sin heladera, congela en un recipiente y remueve vigorosamente cada 30 minutos durante 3–4 ciclos.","image_url":"/recetas/receta-helado-casero/paso-06.webp","image_alt":"Helado casero de vainilla: Bate o congela"},{"title":"Congela y sirve","content":"Congela hasta obtener la firmeza deseada y deja atemperar unos minutos antes de servir en bolas.","image_url":"/recetas/receta-helado-casero/paso-07.webp","image_alt":"Helado casero de vainilla: Congela y sirve"}],"image_url":"/recetas/receta-helado-casero/portada.webp","gallery":[{"url":"/recetas/receta-helado-casero/portada.webp","alt":"Helado casero de vainilla"}],"notes":"Cocina la crema a fuego bajo y sin dejar de remover: si hierve, las yemas se cuajan y quedan grumos; si pasa, cuélala. Cuanto más fría esté la base antes de batir, más cremoso queda el helado. Contiene lácteos y huevo. En el congelador se conserva hasta 2 semanas bien tapado; con el tiempo desarrolla cristales de hielo. Para una vainilla más intensa, infusiona una vaina abierta en la leche caliente en el paso 1 y retírala antes de templar las yemas.","nutrition":{"calories":264,"protein_g":3.8,"carbs_g":28,"fat_g":15.6,"sodium_mg":29,"serving_size":"1 ración (1/6 de la receta)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Suma de nutrientes por 100 g multiplicados por los pesos de los ingredientes y divididos entre 6. La crema de leche (200 ml) se calcula a 190 g, la leche (200 ml) a 206 g, las 4 yemas a 68 g y la vainilla (5 ml) a 4 g.","note":"Estimación por ración; varía con el contenido graso de la crema, el tamaño de las yemas y las marcas. Se usa el valor USDA de crema para batir.","inputs":[{"fdc_id":"170859","description":"Cream, fluid, heavy whipping","grams":190,"per100":{"calories":340,"protein_g":2.84,"carbs_g":2.74,"fat_g":36.08,"saturated_fat_g":22.76,"fiber_g":0,"sodium_mg":27}},{"fdc_id":"172217","description":"Milk, whole, 3.25% milkfat, without added vitamin A and vitamin D","grams":206,"per100":{"calories":61,"protein_g":3.15,"carbs_g":4.78,"fat_g":3.27,"saturated_fat_g":1.86,"fiber_g":0,"sodium_mg":43}},{"fdc_id":"169655","description":"Sugars, granulated","grams":150,"per100":{"calories":387,"protein_g":0,"carbs_g":99.98,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sodium_mg":1}},{"fdc_id":"172186","description":"Egg, yolk, raw, fresh","grams":68,"per100":{"calories":322,"protein_g":15.86,"carbs_g":3.59,"fat_g":26.54,"saturated_fat_g":9.551,"fiber_g":0,"sodium_mg":48}},{"fdc_id":"173471","description":"Vanilla extract","grams":4,"per100":{"calories":288,"protein_g":0.06,"carbs_g":12.65,"fat_g":0.06,"saturated_fat_g":0.01,"fiber_g":0,"sodium_mg":9}}]},"seo":{"title":"Helado casero de vainilla con yemas | Manual de Cocina","description":"Helado casero de vainilla con crema de leche, leche, yemas y azúcar. Con o sin heladera, rinde 6 raciones y queda cremoso. Paso a paso.","image_variants":["/recetas/receta-helado-casero/portada-1x1.webp","/recetas/receta-helado-casero/portada-4x3.webp","/recetas/receta-helado-casero/portada-16x9.webp"],"faq":[{"q":"¿Puedo hacer este helado sin heladera?","a":"Sí. Congela la base fría en un recipiente y remuévela con fuerza cada 30 minutos durante 3–4 ciclos para romper los cristales de hielo; después congela hasta que esté firme."},{"q":"¿Por qué mi helado queda con cristales de hielo?","a":"Suele ser porque la base no estaba bien fría antes de batir o no se removió lo suficiente al congelar. Refrigera la crema al menos 4 horas y, sin heladera, remueve cada 30 minutos."},{"q":"¿Cuánto dura el helado casero?","a":"Se conserva hasta 2 semanas en el congelador en un recipiente bien tapado. Déjalo atemperar unos minutos antes de servir para que sea fácil de formar en bolas."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"cc9e49f9-b361-57ee-adbd-426965b62be6","recipe_group_id":"b7214663-c9ba-4062-b363-d651d2faec96","language":"de","slug":"hausgemachtes-vanilleeis","public_path":"/de/hausgemachtes-vanilleeis","source_url":null,"title":"Hausgemachtes Vanilleeis","excerpt":"Cremiges Vanilleeis aus Sahne, Milch, Eigelb und Zucker, mit oder ohne Eismaschine. Ergibt 6 Portionen; benötigt 4 Stunden Kühlzeit.","summary":"Dieses selbstgemachte Vanilleeis basiert auf einer Vanillecreme: Sahne und Milch werden mit Zucker erhitzt, über Eigelb temperiert und gegart, bis die Masse einen Löffelrücken überzieht. Danach wird sie gekühlt, mit Vanilleextrakt aromatisiert und in der Eismaschine gerührt oder im Gefrierfach durch Umrühren gefroren.\n\nDas Ergebnis ist ein weiches Eis mit reinem Vanillegeschmack und cremiger Textur. Ergibt 6 Portionen und braucht etwa 4 Stunden Kühlzeit vor dem Gefrieren.","category":"Desserts","difficulty":"Einfach","course":"Dessert","cuisine":"Kalte Desserts","prep_time_minutes":25,"cook_time_minutes":15,"total_time_minutes":280,"servings":6,"keywords":["Vanilleeis selber machen","Vanilleeis","Eis Rezept","Eis mit Eigelb","Eis ohne Eismaschine","kaltes Dessert"],"ingredients":[{"name":"Sahne","amount":"200","unit":"ml","group":"Cremebasis"},{"name":"Vollmilch","amount":"200","unit":"ml","group":"Cremebasis"},{"name":"Zucker","amount":"150","unit":"g","group":"Cremebasis"},{"name":"Eigelb","amount":"4","unit":"Stück","group":"Cremebasis"},{"name":"Vanilleextrakt","amount":"5","unit":"ml","group":"Zum Aromatisieren"}],"steps":[{"title":"Sahne und Milch erhitzen","content":"In einem Topf 200 ml Sahne und 200 ml Milch bei mittlerer Hitze erwärmen, ohne dass sie kochen. 150 g Zucker zugeben und rühren, bis er sich aufgelöst hat.","image_url":"/recetas/receta-helado-casero/paso-01.webp","image_alt":"Hausgemachtes Vanilleeis: Sahne und Milch erhitzen"},{"title":"Eigelb verquirlen","content":"In einer separaten Schüssel 4 Eigelb mit einem Schneebesen verquirlen.","image_url":"/recetas/receta-helado-casero/paso-02.webp","image_alt":"Hausgemachtes Vanilleeis: Eigelb verquirlen"},{"title":"Eigelb temperieren","content":"Einen Teil der heißen Mischung langsam unter ständigem Rühren auf das Eigelb gießen, um es zu temperieren, ohne dass es gerinnt.","image_url":"/recetas/receta-helado-casero/paso-03.webp","image_alt":"Hausgemachtes Vanilleeis: Eigelb temperieren"},{"title":"Creme garen","content":"Alles zurück in den Topf geben und bei mittlerer bis niedriger Hitze unter Rühren garen, bis die Creme leicht eindickt und den Rücken eines Löffels überzieht.","image_url":"/recetas/receta-helado-casero/paso-04.webp","image_alt":"Hausgemachtes Vanilleeis: Creme garen"},{"title":"Creme abkühlen","content":"Vom Herd nehmen, abkühlen lassen und mindestens 4 Stunden kühlen, mit Frischhaltefolie direkt auf der Oberfläche abgedeckt.","image_url":"/recetas/receta-helado-casero/paso-05.webp","image_alt":"Hausgemachtes Vanilleeis: Creme abkühlen"},{"title":"Rühren oder gefrieren","content":"5 ml Vanilleextrakt zugeben und in einer Eismaschine nach Anleitung rühren. Ohne Eismaschine in einer Form einfrieren und 3–4 Mal alle 30 Minuten kräftig durchrühren.","image_url":"/recetas/receta-helado-casero/paso-06.webp","image_alt":"Hausgemachtes Vanilleeis: Rühren oder gefrieren"},{"title":"Gefrieren und servieren","content":"Bis zur gewünschten Festigkeit gefrieren und vor dem Servieren einige Minuten antauen lassen, dann Kugeln formen.","image_url":"/recetas/receta-helado-casero/paso-07.webp","image_alt":"Hausgemachtes Vanilleeis: Gefrieren und servieren"}],"image_url":"/recetas/receta-helado-casero/portada.webp","gallery":[{"url":"/recetas/receta-helado-casero/portada.webp","alt":"Hausgemachtes Vanilleeis"}],"notes":"Die Creme bei niedriger Hitze und unter ständigem Rühren garen: Kocht sie, gerinnt das Eigelb und es entstehen Klümpchen; dann durch ein Sieb streichen. Je kälter die Basis vor dem Rühren ist, desto cremiger wird das Eis. Enthält Milch und Ei. Gut verschlossen hält es sich bis zu 2 Wochen im Gefrierfach und bildet mit der Zeit Eiskristalle. Für ein intensiveres Vanillearoma eine aufgeschnittene Vanilleschote in Schritt 1 in der Milch ziehen lassen und vor dem Temperieren entfernen.","nutrition":{"calories":264,"protein_g":3.8,"carbs_g":28,"fat_g":15.6,"sodium_mg":29,"serving_size":"1 Portion (1/6 des Rezepts)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Nährwerte je 100 g, multipliziert mit dem Gewicht der Zutaten und durch 6 geteilt. Die Sahne (200 ml) wird mit 190 g gerechnet, die Milch (200 ml) mit 206 g, die 4 Eigelb mit 68 g und die Vanille (5 ml) mit 4 g.","note":"Schätzung pro Portion; abhängig vom Fettgehalt der Sahne, der Größe der Eigelbe und von Marken. Verwendet wird der USDA-Wert für Schlagsahne."},"seo":{"title":"Hausgemachtes Vanilleeis mit Eigelb | Manual de Cocina","description":"Hausgemachtes Vanilleeis aus Sahne, Milch, Eigelb und Zucker. Mit oder ohne Eismaschine, ergibt 6 Portionen und wird cremig. Schritt für Schritt.","image_variants":["/recetas/receta-helado-casero/portada-1x1.webp","/recetas/receta-helado-casero/portada-4x3.webp","/recetas/receta-helado-casero/portada-16x9.webp"],"faq":[{"q":"Kann ich dieses Eis ohne Eismaschine machen?","a":"Ja. Die kalte Basis in einer Form einfrieren und 3–4 Mal alle 30 Minuten kräftig durchrühren, um Eiskristalle aufzubrechen; danach fest durchfrieren."},{"q":"Warum hat mein Eis Eiskristalle?","a":"Meist war die Basis vor dem Rühren nicht kalt genug oder wurde beim Gefrieren zu wenig gerührt. Die Creme mindestens 4 Stunden kühlen und ohne Eismaschine alle 30 Minuten rühren."},{"q":"Wie lange hält selbstgemachtes Eis?","a":"Gut verschlossen bis zu 2 Wochen im Gefrierfach. Vor dem Servieren einige Minuten antauen lassen, damit sich Kugeln leicht formen lassen."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"e8ed5f14-1ebc-5161-98ff-e993f0c85025","recipe_group_id":"b7214663-c9ba-4062-b363-d651d2faec96","language":"en","slug":"homemade-vanilla-ice-cream","public_path":"/en/homemade-vanilla-ice-cream","source_url":null,"title":"Homemade Vanilla Ice Cream","excerpt":"Creamy vanilla ice cream made from cream, milk, egg yolks and sugar, with or without an ice cream maker. Serves 6; needs 4 hours of chilling.","summary":"This homemade vanilla ice cream starts from a custard base: cream and milk are heated with sugar, tempered into egg yolks and cooked until thick enough to coat the back of a spoon. The base is then chilled, flavored with vanilla extract and churned in an ice cream maker or frozen with regular stirring.\n\nThe result is a soft ice cream with a clean vanilla flavor and creamy texture. It serves 6 and needs about 4 hours of chilling before freezing.","category":"Desserts","difficulty":"Easy","course":"Dessert","cuisine":"Frozen desserts","prep_time_minutes":25,"cook_time_minutes":15,"total_time_minutes":280,"servings":6,"keywords":["homemade vanilla ice cream","vanilla ice cream","ice cream recipe","custard ice cream","no-churn ice cream","cold dessert"],"ingredients":[{"name":"heavy cream","amount":"200","unit":"ml","group":"Custard base"},{"name":"whole milk","amount":"200","unit":"ml","group":"Custard base"},{"name":"sugar","amount":"150","unit":"g","group":"Custard base"},{"name":"egg yolks","amount":"4","unit":"piece","group":"Custard base"},{"name":"vanilla extract","amount":"5","unit":"ml","group":"To flavor"}],"steps":[{"title":"Heat the cream and milk","content":"In a saucepan, heat 200 ml cream and 200 ml milk over medium heat without letting them boil. Add 150 g sugar and stir until dissolved.","image_url":"/recetas/receta-helado-casero/paso-01.webp","image_alt":"Homemade Vanilla Ice Cream: Heat the cream and milk"},{"title":"Whisk the yolks","content":"In a separate bowl, whisk 4 egg yolks.","image_url":"/recetas/receta-helado-casero/paso-02.webp","image_alt":"Homemade Vanilla Ice Cream: Whisk the yolks"},{"title":"Temper the yolks","content":"Slowly pour part of the hot mixture over the yolks, whisking constantly, to temper them without scrambling.","image_url":"/recetas/receta-helado-casero/paso-03.webp","image_alt":"Homemade Vanilla Ice Cream: Temper the yolks"},{"title":"Cook the custard","content":"Return everything to the pan and cook over medium-low heat, stirring, until the custard thickens slightly and coats the back of a spoon.","image_url":"/recetas/receta-helado-casero/paso-04.webp","image_alt":"Homemade Vanilla Ice Cream: Cook the custard"},{"title":"Chill the custard","content":"Remove from the heat, let cool and refrigerate at least 4 hours, covered with plastic wrap pressed on the surface.","image_url":"/recetas/receta-helado-casero/paso-05.webp","image_alt":"Homemade Vanilla Ice Cream: Chill the custard"},{"title":"Churn or freeze","content":"Add 5 ml vanilla extract and churn in an ice cream maker following its instructions. Without a machine, freeze in a container and stir vigorously every 30 minutes for 3–4 rounds.","image_url":"/recetas/receta-helado-casero/paso-06.webp","image_alt":"Homemade Vanilla Ice Cream: Churn or freeze"},{"title":"Freeze and serve","content":"Freeze until firm to your liking and let it soften for a few minutes before scooping.","image_url":"/recetas/receta-helado-casero/paso-07.webp","image_alt":"Homemade Vanilla Ice Cream: Freeze and serve"}],"image_url":"/recetas/receta-helado-casero/portada.webp","gallery":[{"url":"/recetas/receta-helado-casero/portada.webp","alt":"Homemade Vanilla Ice Cream"}],"notes":"Cook the custard over low heat, stirring constantly: if it boils, the yolks curdle and leave lumps; if that happens, strain it. The colder the base is before churning, the creamier the ice cream. Contains dairy and egg. It keeps up to 2 weeks in the freezer when well covered and develops ice crystals over time. For a stronger vanilla flavor, steep a split vanilla bean in the hot milk in step 1 and remove it before tempering the yolks.","nutrition":{"calories":264,"protein_g":3.8,"carbs_g":28,"fat_g":15.6,"sodium_mg":29,"serving_size":"1 serving (1/6 of the recipe)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Nutrients per 100 g multiplied by the weights of the ingredients and divided by 6. The cream (200 ml) is calculated at 190 g, the milk (200 ml) at 206 g, the 4 yolks at 68 g and the vanilla (5 ml) at 4 g.","note":"Estimate per serving; it varies with the fat content of the cream, the size of the yolks and brands. The USDA value for heavy whipping cream is used."},"seo":{"title":"Homemade Vanilla Ice Cream with Egg Yolks | Manual de Cocina","description":"Homemade vanilla ice cream with cream, milk, egg yolks and sugar. With or without an ice cream maker, serves 6 and turns out creamy. Step by step.","image_variants":["/recetas/receta-helado-casero/portada-1x1.webp","/recetas/receta-helado-casero/portada-4x3.webp","/recetas/receta-helado-casero/portada-16x9.webp"],"faq":[{"q":"Can I make this ice cream without an ice cream maker?","a":"Yes. Freeze the cold base in a container and stir it vigorously every 30 minutes for 3–4 rounds to break up ice crystals, then freeze until firm."},{"q":"Why does my ice cream have ice crystals?","a":"Usually the base was not cold enough before churning or was not stirred enough while freezing. Chill the custard at least 4 hours and, without a machine, stir every 30 minutes."},{"q":"How long does homemade ice cream last?","a":"Up to 2 weeks in the freezer in a well-covered container. Let it soften for a few minutes before serving so it scoops easily."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"c4a80cd5-9261-5987-ae7b-e4db10223018","recipe_group_id":"b7214663-c9ba-4062-b363-d651d2faec96","language":"fr","slug":"glace-vanille-maison","public_path":"/fr/glace-vanille-maison","source_url":null,"title":"Glace à la vanille maison","excerpt":"Glace à la vanille crémeuse à base de crème, de lait, de jaunes d’œufs et de sucre, avec ou sans sorbetière. Pour 6 personnes ; 4 heures de repos au froid.","summary":"Cette glace à la vanille maison part d’une crème anglaise : crème et lait chauffés avec le sucre, versés sur les jaunes puis cuits jusqu’à ce que la crème nappe le dos d’une cuillère. Elle est ensuite refroidie, parfumée à l’extrait de vanille et turbinée en sorbetière ou congelée en remuant régulièrement.\n\nLe résultat est une glace douce, au goût net de vanille et à la texture crémeuse. La recette est prévue pour 6 personnes et demande environ 4 heures de réfrigération avant la congélation.","category":"Desserts","difficulty":"Facile","course":"Dessert","cuisine":"Desserts glacés","prep_time_minutes":25,"cook_time_minutes":15,"total_time_minutes":280,"servings":6,"keywords":["glace à la vanille maison","glace vanille","recette de glace maison","glace aux jaunes d’œufs","glace sans sorbetière","dessert glacé"],"ingredients":[{"name":"crème liquide entière","amount":"200","unit":"ml","group":"Base de crème"},{"name":"lait entier","amount":"200","unit":"ml","group":"Base de crème"},{"name":"sucre","amount":"150","unit":"g","group":"Base de crème"},{"name":"jaunes d’œufs","amount":"4","unit":"pièce","group":"Base de crème"},{"name":"extrait de vanille","amount":"5","unit":"ml","group":"Pour parfumer"}],"steps":[{"title":"Chauffer la crème et le lait","content":"Dans une casserole, chauffez à feu moyen 200 ml de crème et 200 ml de lait sans les laisser bouillir. Ajoutez 150 g de sucre et remuez jusqu’à dissolution.","image_url":"/recetas/receta-helado-casero/paso-01.webp","image_alt":"Glace à la vanille maison: Chauffer la crème et le lait"},{"title":"Battre les jaunes","content":"Dans un récipient à part, fouettez 4 jaunes d’œufs.","image_url":"/recetas/receta-helado-casero/paso-02.webp","image_alt":"Glace à la vanille maison: Battre les jaunes"},{"title":"Tempérer les jaunes","content":"Versez peu à peu une partie du mélange chaud sur les jaunes en fouettant sans cesse, pour les tempérer sans les faire cuire.","image_url":"/recetas/receta-helado-casero/paso-03.webp","image_alt":"Glace à la vanille maison: Tempérer les jaunes"},{"title":"Cuire la crème","content":"Remettez le tout dans la casserole et faites cuire à feu moyen-doux en remuant, jusqu’à ce que la crème épaississe légèrement et nappe le dos d’une cuillère.","image_url":"/recetas/receta-helado-casero/paso-04.webp","image_alt":"Glace à la vanille maison: Cuire la crème"},{"title":"Refroidir la crème","content":"Retirez du feu, laissez refroidir puis réfrigérez au moins 4 heures, couverte d’un film au contact de la surface.","image_url":"/recetas/receta-helado-casero/paso-05.webp","image_alt":"Glace à la vanille maison: Refroidir la crème"},{"title":"Turbiner ou congeler","content":"Ajoutez 5 ml d’extrait de vanille et turbinez en sorbetière selon sa notice. Sans sorbetière, congelez dans un récipient en remuant vigoureusement toutes les 30 minutes, 3 à 4 fois.","image_url":"/recetas/receta-helado-casero/paso-06.webp","image_alt":"Glace à la vanille maison: Turbiner ou congeler"},{"title":"Congeler et servir","content":"Congelez jusqu’à la fermeté souhaitée et laissez tempérer quelques minutes avant de servir en boules.","image_url":"/recetas/receta-helado-casero/paso-07.webp","image_alt":"Glace à la vanille maison: Congeler et servir"}],"image_url":"/recetas/receta-helado-casero/portada.webp","gallery":[{"url":"/recetas/receta-helado-casero/portada.webp","alt":"Glace à la vanille maison"}],"notes":"Faites cuire la crème à feu doux en remuant sans cesse : si elle bout, les jaunes coagulent et forment des grumeaux ; dans ce cas, passez-la au tamis. Plus la base est froide avant le turbinage, plus la glace est crémeuse. Contient du lait et des œufs. Elle se conserve jusqu’à 2 semaines au congélateur bien couverte et développe des cristaux de glace avec le temps. Pour une vanille plus intense, faites infuser une gousse fendue dans le lait chaud à l’étape 1 et retirez-la avant de tempérer les jaunes.","nutrition":{"calories":264,"protein_g":3.8,"carbs_g":28,"fat_g":15.6,"sodium_mg":29,"serving_size":"1 portion (1/6 de la recette)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Nutriments pour 100 g multipliés par le poids des ingrédients et divisés par 6. La crème (200 ml) est calculée à 190 g, le lait (200 ml) à 206 g, les 4 jaunes à 68 g et la vanille (5 ml) à 4 g.","note":"Estimation par portion ; elle varie selon la teneur en matières grasses de la crème, la taille des jaunes et les marques. On utilise la valeur USDA de la crème à fouetter."},"seo":{"title":"Glace à la vanille maison aux jaunes d’œufs | Manual de Cocina","description":"Glace à la vanille maison avec crème, lait, jaunes d’œufs et sucre. Avec ou sans sorbetière, pour 6 personnes et bien crémeuse. Pas à pas.","image_variants":["/recetas/receta-helado-casero/portada-1x1.webp","/recetas/receta-helado-casero/portada-4x3.webp","/recetas/receta-helado-casero/portada-16x9.webp"],"faq":[{"q":"Puis-je faire cette glace sans sorbetière ?","a":"Oui. Congelez la base froide dans un récipient et remuez-la vigoureusement toutes les 30 minutes, 3 à 4 fois, pour casser les cristaux de glace ; congelez ensuite jusqu’à fermeté."},{"q":"Pourquoi ma glace a-t-elle des cristaux de glace ?","a":"En général, la base n’était pas assez froide avant le turbinage ou n’a pas été assez remuée pendant la congélation. Réfrigérez la crème au moins 4 heures et, sans sorbetière, remuez toutes les 30 minutes."},{"q":"Combien de temps se conserve la glace maison ?","a":"Jusqu’à 2 semaines au congélateur dans un récipient bien couvert. Laissez-la tempérer quelques minutes avant de servir pour former facilement des boules."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"1221ba88-3d0a-5ed6-83f5-177ff7ebb112","recipe_group_id":"b7214663-c9ba-4062-b363-d651d2faec96","language":"it","slug":"gelato-alla-vaniglia-fatto-in-casa","public_path":"/it/gelato-alla-vaniglia-fatto-in-casa","source_url":null,"title":"Gelato alla vaniglia fatto in casa","excerpt":"Gelato alla vaniglia cremoso con panna, latte, tuorli e zucchero, con o senza gelatiera. Per 6 porzioni; richiede 4 ore di riposo in frigo.","summary":"Questo gelato alla vaniglia fatto in casa parte da una crema inglese: panna e latte scaldati con lo zucchero, temperati sui tuorli e cotti finché la crema vela il dorso di un cucchiaio. Poi si raffredda, si aromatizza con estratto di vaniglia e si manteca in gelatiera o si congela mescolando.\n\nIl risultato è un gelato morbido, dal gusto netto di vaniglia e dalla consistenza cremosa. Dà 6 porzioni e richiede circa 4 ore di frigorifero prima del congelamento.","category":"Dolci","difficulty":"Facile","course":"Dolce","cuisine":"Dolci freddi","prep_time_minutes":25,"cook_time_minutes":15,"total_time_minutes":280,"servings":6,"keywords":["gelato alla vaniglia fatto in casa","gelato alla vaniglia","ricetta del gelato","gelato con tuorli","gelato senza gelatiera","dolce freddo"],"ingredients":[{"name":"panna fresca","amount":"200","unit":"ml","group":"Base di crema"},{"name":"latte intero","amount":"200","unit":"ml","group":"Base di crema"},{"name":"zucchero","amount":"150","unit":"g","group":"Base di crema"},{"name":"tuorli","amount":"4","unit":"pezzo","group":"Base di crema"},{"name":"estratto di vaniglia","amount":"5","unit":"ml","group":"Per aromatizzare"}],"steps":[{"title":"Scalda la panna e il latte","content":"In un pentolino, scalda a fuoco medio 200 ml di panna e 200 ml di latte senza farli bollire. Aggiungi 150 g di zucchero e mescola finché si scioglie.","image_url":"/recetas/receta-helado-casero/paso-01.webp","image_alt":"Gelato alla vaniglia fatto in casa: Scalda la panna e il latte"},{"title":"Sbatti i tuorli","content":"In una ciotola a parte, sbatti 4 tuorli con una frusta.","image_url":"/recetas/receta-helado-casero/paso-02.webp","image_alt":"Gelato alla vaniglia fatto in casa: Sbatti i tuorli"},{"title":"Tempera i tuorli","content":"Versa poco alla volta una parte del composto caldo sui tuorli, mescolando di continuo, per temperarli senza farli rapprendere.","image_url":"/recetas/receta-helado-casero/paso-03.webp","image_alt":"Gelato alla vaniglia fatto in casa: Tempera i tuorli"},{"title":"Cuoci la crema","content":"Rimetti tutto nel pentolino e cuoci a fuoco medio-basso mescolando, finché la crema si addensa leggermente e vela il dorso di un cucchiaio.","image_url":"/recetas/receta-helado-casero/paso-04.webp","image_alt":"Gelato alla vaniglia fatto in casa: Cuoci la crema"},{"title":"Raffredda la crema","content":"Togli dal fuoco, lascia raffreddare e metti in frigorifero almeno 4 ore, coperta con pellicola a contatto con la superficie.","image_url":"/recetas/receta-helado-casero/paso-05.webp","image_alt":"Gelato alla vaniglia fatto in casa: Raffredda la crema"},{"title":"Manteca o congela","content":"Aggiungi 5 ml di estratto di vaniglia e manteca in gelatiera seguendo le istruzioni. Senza gelatiera, congela in un contenitore e mescola con energia ogni 30 minuti per 3–4 volte.","image_url":"/recetas/receta-helado-casero/paso-06.webp","image_alt":"Gelato alla vaniglia fatto in casa: Manteca o congela"},{"title":"Congela e servi","content":"Congela fino alla consistenza desiderata e lascia ammorbidire qualche minuto prima di servire a palline.","image_url":"/recetas/receta-helado-casero/paso-07.webp","image_alt":"Gelato alla vaniglia fatto in casa: Congela e servi"}],"image_url":"/recetas/receta-helado-casero/portada.webp","gallery":[{"url":"/recetas/receta-helado-casero/portada.webp","alt":"Gelato alla vaniglia fatto in casa"}],"notes":"Cuoci la crema a fuoco basso mescolando di continuo: se bolle, i tuorli si rapprendono e formano grumi; in quel caso filtrala. Più la base è fredda prima di mantecare, più il gelato risulta cremoso. Contiene latte e uova. Si conserva fino a 2 settimane nel congelatore ben coperto e con il tempo sviluppa cristalli di ghiaccio. Per una vaniglia più intensa, fai infondere un baccello aperto nel latte caldo al passo 1 e toglilo prima di temperare i tuorli.","nutrition":{"calories":264,"protein_g":3.8,"carbs_g":28,"fat_g":15.6,"sodium_mg":29,"serving_size":"1 porzione (1/6 della ricetta)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Nutrienti per 100 g moltiplicati per il peso degli ingredienti e divisi per 6. La panna (200 ml) è calcolata a 190 g, il latte (200 ml) a 206 g, i 4 tuorli a 68 g e la vaniglia (5 ml) a 4 g.","note":"Stima per porzione; varia con il contenuto di grassi della panna, la dimensione dei tuorli e le marche. Si usa il valore USDA della panna da montare."},"seo":{"title":"Gelato alla vaniglia fatto in casa | Manual de Cocina","description":"Gelato alla vaniglia fatto in casa con panna, latte, tuorli e zucchero. Con o senza gelatiera, dà 6 porzioni ed è cremoso. Passo dopo passo.","image_variants":["/recetas/receta-helado-casero/portada-1x1.webp","/recetas/receta-helado-casero/portada-4x3.webp","/recetas/receta-helado-casero/portada-16x9.webp"],"faq":[{"q":"Posso fare questo gelato senza gelatiera?","a":"Sì. Congela la base fredda in un contenitore e mescolala con energia ogni 30 minuti per 3–4 volte per rompere i cristalli di ghiaccio; poi congela fino a farlo diventare sodo."},{"q":"Perché il mio gelato ha cristalli di ghiaccio?","a":"Di solito la base non era abbastanza fredda prima di mantecare o non è stata mescolata abbastanza durante il congelamento. Raffredda la crema almeno 4 ore e, senza gelatiera, mescola ogni 30 minuti."},{"q":"Quanto dura il gelato fatto in casa?","a":"Fino a 2 settimane nel congelatore in un contenitore ben coperto. Lascialo ammorbidire qualche minuto prima di servire per formare facilmente le palline."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"f1be04f1-87f4-502a-8ffd-87fd0d1e75f1","recipe_group_id":"b7214663-c9ba-4062-b363-d651d2faec96","language":"ja","slug":"手作りバニラアイスクリーム","public_path":"/ja/手作りバニラアイスクリーム","source_url":null,"title":"手作りバニラアイスクリーム","excerpt":"生クリーム・牛乳・卵黄・砂糖で作る、なめらかなバニラアイスクリーム。アイスクリームメーカーなしでも作れます。6人分、冷蔵4時間が必要です。","summary":"この手作りバニラアイスは、カスタードソースを土台にします。生クリームと牛乳を砂糖と温め、卵黄に少しずつ加えてなじませ、スプーンの背を覆うくらいまで加熱します。冷やしてバニラエクストラクトを加え、アイスクリームメーカーで撹拌するか、こまめに混ぜながら冷凍します。\n\n素直なバニラの風味となめらかな口当たりに仕上がります。6人分で、冷凍前に約4時間の冷蔵が必要です。","category":"デザート","difficulty":"簡単","course":"デザート","cuisine":"冷たいデザート","prep_time_minutes":25,"cook_time_minutes":15,"total_time_minutes":280,"servings":6,"keywords":["手作りバニラアイス","バニラアイスクリーム","アイスクリームのレシピ","卵黄のアイス","アイスクリームメーカーなし","冷たいデザート"],"ingredients":[{"name":"生クリーム","amount":"200","unit":"ml","group":"カスタードの材料"},{"name":"牛乳","amount":"200","unit":"ml","group":"カスタードの材料"},{"name":"砂糖","amount":"150","unit":"g","group":"カスタードの材料"},{"name":"卵黄","amount":"4","unit":"個","group":"カスタードの材料"},{"name":"バニラエクストラクト","amount":"5","unit":"ml","group":"香りづけ"}],"steps":[{"title":"生クリームと牛乳を温める","content":"鍋に生クリーム200mlと牛乳200mlを入れ、沸騰させないように中火で温めます。砂糖150gを加え、溶けるまで混ぜます。","image_url":"/recetas/receta-helado-casero/paso-01.webp","image_alt":"手作りバニラアイスクリーム: 生クリームと牛乳を温める"},{"title":"卵黄を混ぜる","content":"別のボウルで卵黄4個を泡立て器で混ぜます。","image_url":"/recetas/receta-helado-casero/paso-02.webp","image_alt":"手作りバニラアイスクリーム: 卵黄を混ぜる"},{"title":"卵黄をなじませる","content":"温めた液の一部を、絶えず混ぜながら卵黄に少しずつ注ぎ、固まらないようになじませます。","image_url":"/recetas/receta-helado-casero/paso-03.webp","image_alt":"手作りバニラアイスクリーム: 卵黄をなじませる"},{"title":"カスタードを加熱する","content":"全部を鍋に戻し、弱めの中火で混ぜながら、少しとろみがつき、スプーンの背を覆うくらいまで加熱します。","image_url":"/recetas/receta-helado-casero/paso-04.webp","image_alt":"手作りバニラアイスクリーム: カスタードを加熱する"},{"title":"冷やす","content":"火から下ろして粗熱を取り、表面にラップをぴったり貼って冷蔵庫で4時間以上冷やします。","image_url":"/recetas/receta-helado-casero/paso-05.webp","image_alt":"手作りバニラアイスクリーム: 冷やす"},{"title":"撹拌または冷凍する","content":"バニラエクストラクト5mlを加え、アイスクリームメーカーの説明どおりに撹拌します。機械がない場合は容器に入れて冷凍し、30分ごとに力強く混ぜる作業を3〜4回繰り返します。","image_url":"/recetas/receta-helado-casero/paso-06.webp","image_alt":"手作りバニラアイスクリーム: 撹拌または冷凍する"},{"title":"凍らせて盛りつける","content":"好みの固さまで凍らせ、数分おいて少しやわらかくしてから、丸くすくって盛りつけます。","image_url":"/recetas/receta-helado-casero/paso-07.webp","image_alt":"手作りバニラアイスクリーム: 凍らせて盛りつける"}],"image_url":"/recetas/receta-helado-casero/portada.webp","gallery":[{"url":"/recetas/receta-helado-casero/portada.webp","alt":"手作りバニラアイスクリーム"}],"notes":"カスタードは弱火で絶えず混ぜながら加熱してください。沸騰すると卵黄が固まってダマになります。そのときは裏ごししてください。撹拌前の液が冷たいほど、なめらかに仕上がります。乳と卵を含みます。しっかり蓋をして冷凍で2週間まで保存できますが、時間とともに氷の結晶ができます。バニラの香りを強くしたいときは、手順1で縦に割ったバニラビーンズを温かい牛乳に浸し、卵黄に加える前に取り除きます。","nutrition":{"calories":264,"protein_g":3.8,"carbs_g":28,"fat_g":15.6,"sodium_mg":29,"serving_size":"1人分（レシピの1/6）","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"100gあたりの栄養成分に材料の重量を掛けて合計し、6で割りました。生クリーム（200ml）は190g、牛乳（200ml）は206g、卵黄4個は68g、バニラ（5ml）は4gで計算しています。","note":"1人分の推定値です。生クリームの脂肪分、卵黄の大きさ、商品によって異なります。USDAのホイッピングクリームの値を使っています。"},"seo":{"title":"手作りバニラアイスクリーム | Manual de Cocina","description":"生クリーム・牛乳・卵黄・砂糖で作る手作りバニラアイス。アイスクリームメーカーなしでも作れて、6人分。なめらかに仕上がる作り方です。","image_variants":["/recetas/receta-helado-casero/portada-1x1.webp","/recetas/receta-helado-casero/portada-4x3.webp","/recetas/receta-helado-casero/portada-16x9.webp"],"faq":[{"q":"アイスクリームメーカーなしで作れますか？","a":"はい。冷やした液を容器に入れて冷凍し、30分ごとに力強く混ぜる作業を3〜4回繰り返して氷の結晶を細かくし、その後しっかり凍らせます。"},{"q":"氷の結晶ができてしまうのはなぜですか？","a":"撹拌前の液が十分に冷えていなかったか、冷凍中の混ぜ方が足りないことが多いです。カスタードを4時間以上冷やし、機械がない場合は30分ごとに混ぜてください。"},{"q":"手作りアイスはどのくらい保存できますか？","a":"しっかり蓋をした容器で、冷凍で2週間までです。盛りつける前に数分おいてやわらかくすると、すくいやすくなります。"}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"44538990-349f-5117-8ed3-91a9781b988b","recipe_group_id":"b7214663-c9ba-4062-b363-d651d2faec96","language":"pt","slug":"sorvete-caseiro-de-baunilha","public_path":"/pt/sorvete-caseiro-de-baunilha","source_url":null,"title":"Sorvete caseiro de baunilha","excerpt":"Sorvete de baunilha cremoso com creme de leite, leite, gemas e açúcar, com ou sem sorveteira. Rende 6 porções; precisa de 4 horas de geladeira.","summary":"Este sorvete caseiro de baunilha parte de um creme inglês: creme de leite e leite aquecidos com açúcar, temperados sobre as gemas e cozidos até cobrir as costas de uma colher. Depois é resfriado, aromatizado com extrato de baunilha e batido na sorveteira ou congelado mexendo de vez em quando.\n\nO resultado é um sorvete macio, com sabor limpo de baunilha e textura cremosa. Rende 6 porções e precisa de cerca de 4 horas de geladeira antes de ir ao congelador.","category":"Sobremesas","difficulty":"Fácil","course":"Sobremesa","cuisine":"Sobremesas geladas","prep_time_minutes":25,"cook_time_minutes":15,"total_time_minutes":280,"servings":6,"keywords":["sorvete caseiro de baunilha","sorvete de baunilha","receita de sorvete caseiro","sorvete com gemas","sorvete sem sorveteira","sobremesa gelada"],"ingredients":[{"name":"creme de leite fresco","amount":"200","unit":"ml","group":"Base de creme"},{"name":"leite integral","amount":"200","unit":"ml","group":"Base de creme"},{"name":"açúcar","amount":"150","unit":"g","group":"Base de creme"},{"name":"gemas de ovo","amount":"4","unit":"unidade","group":"Base de creme"},{"name":"extrato de baunilha","amount":"5","unit":"ml","group":"Para aromatizar"}],"steps":[{"title":"Aqueça o creme de leite e o leite","content":"Em uma panela, aqueça em fogo médio 200 ml de creme de leite e 200 ml de leite, sem deixar ferver. Junte 150 g de açúcar e mexa até dissolver.","image_url":"/recetas/receta-helado-casero/paso-01.webp","image_alt":"Sorvete caseiro de baunilha: Aqueça o creme de leite e o leite"},{"title":"Bata as gemas","content":"Em uma tigela à parte, bata 4 gemas com um fouet.","image_url":"/recetas/receta-helado-casero/paso-02.webp","image_alt":"Sorvete caseiro de baunilha: Bata as gemas"},{"title":"Tempere as gemas","content":"Despeje aos poucos parte da mistura quente sobre as gemas, mexendo sem parar, para temperá-las sem talhar.","image_url":"/recetas/receta-helado-casero/paso-03.webp","image_alt":"Sorvete caseiro de baunilha: Tempere as gemas"},{"title":"Cozinhe o creme","content":"Volte tudo para a panela e cozinhe em fogo médio-baixo, mexendo, até o creme engrossar levemente e cobrir as costas de uma colher.","image_url":"/recetas/receta-helado-casero/paso-04.webp","image_alt":"Sorvete caseiro de baunilha: Cozinhe o creme"},{"title":"Resfrie o creme","content":"Retire do fogo, deixe esfriar e leve à geladeira por pelo menos 4 horas, coberto com filme plástico em contato com a superfície.","image_url":"/recetas/receta-helado-casero/paso-05.webp","image_alt":"Sorvete caseiro de baunilha: Resfrie o creme"},{"title":"Bata ou congele","content":"Acrescente 5 ml de extrato de baunilha e bata na sorveteira seguindo as instruções. Sem sorveteira, congele em um recipiente e mexa vigorosamente a cada 30 minutos, de 3 a 4 vezes.","image_url":"/recetas/receta-helado-casero/paso-06.webp","image_alt":"Sorvete caseiro de baunilha: Bata ou congele"},{"title":"Congele e sirva","content":"Congele até a firmeza desejada e deixe amolecer alguns minutos antes de servir em bolas.","image_url":"/recetas/receta-helado-casero/paso-07.webp","image_alt":"Sorvete caseiro de baunilha: Congele e sirva"}],"image_url":"/recetas/receta-helado-casero/portada.webp","gallery":[{"url":"/recetas/receta-helado-casero/portada.webp","alt":"Sorvete caseiro de baunilha"}],"notes":"Cozinhe o creme em fogo baixo, mexendo sempre: se ferver, as gemas talham e formam grumos; se isso acontecer, coe o creme. Quanto mais gelada estiver a base antes de bater, mais cremoso fica o sorvete. Contém leite e ovo. Dura até 2 semanas no congelador, bem tampado, e com o tempo forma cristais de gelo. Para uma baunilha mais intensa, deixe uma fava aberta em infusão no leite quente no passo 1 e retire-a antes de temperar as gemas.","nutrition":{"calories":264,"protein_g":3.8,"carbs_g":28,"fat_g":15.6,"sodium_mg":29,"serving_size":"1 porção (1/6 da receita)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Nutrientes por 100 g multiplicados pelo peso dos ingredientes e divididos por 6. O creme de leite (200 ml) é calculado a 190 g, o leite (200 ml) a 206 g, as 4 gemas a 68 g e a baunilha (5 ml) a 4 g.","note":"Estimativa por porção; varia conforme o teor de gordura do creme, o tamanho das gemas e as marcas. Usa-se o valor do USDA para creme de leite para bater."},"seo":{"title":"Sorvete caseiro de baunilha com gemas | Manual de Cocina","description":"Sorvete caseiro de baunilha com creme de leite, leite, gemas e açúcar. Com ou sem sorveteira, rende 6 porções e fica cremoso. Passo a passo.","image_variants":["/recetas/receta-helado-casero/portada-1x1.webp","/recetas/receta-helado-casero/portada-4x3.webp","/recetas/receta-helado-casero/portada-16x9.webp"],"faq":[{"q":"Posso fazer este sorvete sem sorveteira?","a":"Pode. Congele a base gelada em um recipiente e mexa vigorosamente a cada 30 minutos, de 3 a 4 vezes, para quebrar os cristais de gelo; depois congele até firmar."},{"q":"Por que meu sorvete fica com cristais de gelo?","a":"Geralmente a base não estava gelada o bastante antes de bater ou não foi mexida o suficiente ao congelar. Resfrie o creme por pelo menos 4 horas e, sem sorveteira, mexa a cada 30 minutos."},{"q":"Quanto tempo dura o sorvete caseiro?","a":"Até 2 semanas no congelador, em recipiente bem tampado. Deixe amolecer alguns minutos antes de servir para formar as bolas com facilidade."}]},"published":true,"editorial_status":"published","content_html":""}
]$j$::jsonb;
  ts constant timestamptz := now();
  n int;
begin
  if (select count(*) from public.recipes where recipe_group_id = g) <> 1
     or not exists (select 1 from public.recipes where id = es_id and language = 'es' and published = false and public_path = '/receta-helado-casero') then
    raise exception 'Estado previo inesperado del grupo';
  end if;
  if exists (select 1 from public.recipes where id <> es_id and (public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)
      or (language, slug) in (select x->>'language', x->>'slug' from jsonb_array_elements(j) x))) then
    raise exception 'Colisión de slug/public_path';
  end if;
  if exists (select 1 from public.content_pages where public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)) then
    raise exception 'Colisión con content_pages';
  end if;

  update public.recipes r set
    title = x.title, excerpt = x.excerpt, summary = x.summary, ingredients = x.ingredients, steps = x.steps,
    category = x.category, prep_time_minutes = x.prep_time_minutes, cook_time_minutes = x.cook_time_minutes,
    total_time_minutes = x.total_time_minutes, servings = x.servings, image_url = x.image_url,
    content_html = x.content_html, notes = x.notes, difficulty = x.difficulty, course = x.course,
    cuisine = x.cuisine, keywords = x.keywords, nutrition = x.nutrition, gallery = x.gallery, seo = x.seo,
    editorial_status = 'published', ready_at = ts, published = true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where r.id = es_id and x.language = 'es';
  get diagnostics n = row_count;
  if n <> 1 then raise exception 'UPDATE ES afectó % filas', n; end if;

  insert into public.recipes (id, recipe_group_id, language, slug, public_path, source_url, title, excerpt, summary,
    ingredients, steps, category, prep_time_minutes, cook_time_minutes, total_time_minutes, servings, image_url,
    content_html, notes, difficulty, course, cuisine, keywords, nutrition, gallery, seo, editorial_status, ready_at, published)
  select x.id, g, x.language, x.slug, x.public_path, null, x.title, x.excerpt, x.summary,
    x.ingredients, x.steps, x.category, x.prep_time_minutes, x.cook_time_minutes, x.total_time_minutes, x.servings, x.image_url,
    '', x.notes, x.difficulty, x.course, x.cuisine, x.keywords,
    x.nutrition || jsonb_build_object('inputs', (select nutrition->'inputs' from public.recipes where id = es_id)),
    x.gallery, x.seo, 'published', ts, true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where x.language <> 'es';
  get diagnostics n = row_count;
  if n <> 6 then raise exception 'INSERT afectó % filas', n; end if;

  if (select count(*) from public.recipes where recipe_group_id = g and published and editorial_status = 'published'
        and language in ('es','de','en','fr','it','ja','pt')) <> 7 then
    raise exception 'El grupo no quedó con 7 filas publicadas';
  end if;
end
$pub$;
